{
  "title": "Tính bán kính đường tròn thiết diện của hình trụ",
  "description": "Chương trình này dựng hình trụ và mặt phẳng cắt vuông góc với trục tại trung điểm, sau đó tính bán kính của đường tròn giao tuyến.",
  "memory_declarations": [
    {
      "name": "O",
      "type": "point3",
      "source_fact_id": "cylinder_bases_O_O_prime"
    },
    {
      "name": "O_prime",
      "type": "point3",
      "source_fact_id": "cylinder_bases_O_O_prime"
    },
    {
      "name": "A",
      "type": "point3",
      "source_fact_id": "radius_base"
    },
    {
      "name": "cylinder",
      "type": "curved_solid",
      "source_fact_id": "cylinder_bases_O_O_prime"
    },
    {
      "name": "M",
      "type": "point3",
      "source_fact_id": "plane_at_midpoint_OO_prime"
    },
    {
      "name": "axis_OO_prime",
      "type": "line3"
    },
    {
      "name": "cutting_plane",
      "type": "plane3",
      "source_fact_id": "plane_perpendicular_axis"
    },
    {
      "name": "C",
      "type": "section",
      "source_fact_id": "intersection_is_circle_C"
    },
    {
      "name": "ban_kinh_C",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "O",
      "at": [0, 0, 0],
      "label": "Tâm đáy dưới của hình trụ"
    },
    {
      "kind": "declare_point",
      "target_var": "O_prime",
      "at": [0, 0, 8],
      "model_assumption": "Chiều cao OO' = 8",
      "source_fact_id": "height_OO_prime",
      "label": "Tâm đáy trên của hình trụ"
    },
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [5, 0, 0],
      "model_assumption": "Bán kính đáy bằng 5",
      "source_fact_id": "radius_base",
      "label": "Một điểm trên vành đáy dưới"
    },
    {
      "kind": "construct_curved_solid",
      "target_var": "cylinder",
      "curved_kind": "cylinder",
      "anchor": "O",
      "apex_or_top": "O_prime",
      "rim_point": "A",
      "label": "Hình trụ đã cho"
    },
    {
      "kind": "construct_point",
      "target_var": "M",
      "expr": {
        "kind": "midpoint",
        "a": "O",
        "b": "O_prime"
      },
      "label": "Trung điểm của trục OO'"
    },
    {
      "kind": "construct_line",
      "target_var": "axis_OO_prime",
      "through_a": "O",
      "through_b": "O_prime",
      "label": "Trục của hình trụ"
    },
    {
      "kind": "assign",
      "target_var": "cutting_plane",
      "expr": {
        "kind": "plane_perpendicular_to_line",
        "point": "M",
        "line": "axis_OO_prime"
      },
      "label": "Mặt phẳng vuông góc với trục tại trung điểm M"
    },
    {
      "kind": "construct_section",
      "target_var": "C",
      "solid": "cylinder",
      "plane": "cutting_plane",
      "label": "Đường tròn (C) là giao tuyến của mặt phẳng và hình trụ"
    },
    {
      "kind": "assign",
      "target_var": "ban_kinh_C",
      "expr": {
        "kind": "measure",
        "quantity": "radius",
        "of": "C"
      },
      "label": "Bán kính của đường tròn (C)"
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa rằng một mặt phẳng cắt hình trụ vuông góc với trục sẽ tạo ra một thiết diện là đường tròn có bán kính bằng bán kính đáy của hình trụ."
}

